function create_movie_post_type() {
    register_post_type('movies',
        array(
            'labels' => array(
                'name' => __('Movies'),
                'singular_name' => __('Movie')
            ),
            'public' => true,
            'has_archive' => true,
            'supports' => array('title', 'editor', 'thumbnail'),
            'menu_icon' => 'dashicons-video-alt3',
        )
    );
}
add_action('init', 'create_movie_post_type');

function theme_enqueue_assets() {
    wp_enqueue_style('main-style', get_stylesheet_uri());
    wp_enqueue_script('custom-js', get_template_directory_uri() . '/js/main.js', array('jquery'), '1.0', true);
}
add_action('wp_enqueue_scripts', 'theme_enqueue_assets');

function greeting_shortcode($atts) {
    $a = shortcode_atts(array(
        'name' => 'Friend'
    ), $atts);
    return "Hello, " . esc_html($a['name']) . "!";
}
add_shortcode('greet', 'greeting_shortcode');

// Usage: [greet name="John"]

add_action('rest_api_init', function () {
  register_rest_route('mytheme/v1', '/latest-posts', array(
    'methods' => 'GET',
    'callback' => 'get_latest_posts_custom',
  ));
});

function get_latest_posts_custom($data) {
  $posts = get_posts(array('numberposts' => 5));
  return $posts;
}
